'use strict';
// Browser recreations, not firmware emulation or verified original level data.
const phones={1100:{year:2003,games:['Space Impact +','Snake II'],ids:['impact','snake']},3310:{year:2000,games:['Snake II','Space Impact','Bantumi','Pairs II'],ids:['snake','impact','bantumi','pairs']},6600:{year:2003,games:['Snake EX recreation','Mix Pix'],ids:['snake','mix']},3220:{year:2004,games:['Club Pinball','Dance Delight','Phantom Spider'],ids:['pinball','dance','spider']}};
let phoneId='1100',extra=null,extraState=null;
const baseAction=action,baseDraw=draw,baseUpdate=update;
const lobby=document.querySelector('#lobby'),shell=document.querySelector('.phone');
for(const id of ['1100','6600','3220','3310']){const b=document.createElement('button');b.className='phone-card';b.innerHTML=`<span class="mini m${id}" aria-hidden="true"><i></i><b></b></span><strong>Nokia ${id}</strong><small>${phones[id].year} · ${phones[id].games.length} games</small><span>Pick up & play →</span>`;b.onclick=()=>selectPhone(id);document.querySelector('.phone-grid').append(b)}
function selectPhone(id){phoneId=id;extra=null;extraState=null;gameChoice=0;state='games';held.clear();pointerKeys.clear();shell.classList.remove('off');shell.dataset.model=id;shell.setAttribute('aria-label',`Nokia ${id} simulator`);document.body.classList.remove('choosing');lobby.hidden=true;document.querySelector('#phones').hidden=false;document.querySelector('.model').textContent=id;document.querySelector('.navi').textContent=['6600','3220'].includes(id)?'●':'−';ink=['6600','3220'].includes(id)?'#173550':'#24351e';paper=['6600','3220'].includes(id)?'#dce8ef':'#9fac73';canvas.setAttribute('aria-label',`Nokia ${id} game screen`);document.querySelector('.desktop-note>span').textContent='NOKIA '+id;document.querySelector('.desktop-note a').href='https://en.wikipedia.org/wiki/Nokia_'+id;document.querySelector('.desktop-note small').textContent='Playable recreations · Unverified original levels';document.querySelector('.navi').focus();}
document.querySelector('#phones').onclick=()=>{pauseHidden();document.body.classList.add('choosing');lobby.hidden=false;document.querySelector('#phones').hidden=true;document.querySelector('.phone-card').focus()};
const help={bantumi:['4 / 6: choose a pit','5: sow your seeds','Capture opposite seeds','Last seed in store: again','Most seeds wins'],pairs:['2 4 6 8: move cursor','5: reveal a card','Find every matching pair','Fewer turns is better'],mix:['2 4 6 8: move blank','Arrange tiles 1 through 15','Empty tile at bottom right','Every shuffle is solvable'],pinball:['4 / 6: hold flippers','5: launch the ball','Hit bumpers for points','Three balls per game'],dance:['2 4 6 8: match arrows','Hit when notes reach line','Build a combo for points','Finish three songs'],spider:['4 / 6: move','Hold 5: shoot','Avoid spiders and shots','Clear six waves to win']};
function startExtra(){state='play';held.clear();const a=extraState={t:0,points:0,cursor:0,moves:0,lives:3,stage:1,items:[],shots:[],cool:0};if(extra==='bantumi'){a.pits=Array(14).fill(4);a.pits[6]=a.pits[13]=0;a.turn=0;a.cursor=0;a.message='Your turn'}if(extra==='pairs'){a.cards=Array.from({length:16},(_,i)=>Math.floor(i/2));for(let i=15;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a.cards[i],a.cards[j]]=[a.cards[j],a.cards[i]]}a.open=[];a.matched=new Set();a.wait=0}if(extra==='mix'){a.tiles=Array.from({length:16},(_,i)=>(i+1)%16);a.blank=15;for(let i=0;i<250;i++){const opts=[-4,4,-1,1].filter(d=>a.blank+d>=0&&a.blank+d<16&&(Math.abs(d)===4||Math.floor(a.blank/4)===Math.floor((a.blank+d)/4)));const n=a.blank+opts[Math.floor(Math.random()*opts.length)];[a.tiles[n],a.tiles[a.blank]]=[a.tiles[a.blank],a.tiles[n]];a.blank=n}}if(extra==='pinball')a.ball={x:177,y:108,vx:0,vy:0,ready:true};if(extra==='dance'){a.schedule=Array.from({length:72},(_,i)=>({lane:(i*7+Math.floor(i/8))%4,at:2+i*.65,done:false}));a.combo=0;a.hits=0}if(extra==='spider'){a.x=96;a.inv=0;spiderWave()}}
function spiderWave(){const a=extraState;a.items=Array.from({length:5+a.stage},(_,i)=>({x:15+(i%7)*24,y:28+Math.floor(i/7)*18,hp:1+Math.floor(a.stage/3),base:15+(i%7)*24}));a.cool=.5;a.shots=[];a.t=0}
function sow(a,p,side){let n=a.pits[p];if(!n)return false;a.pits[p]=0;while(n){p=(p+1)%14;if(p===(side===0?13:6))continue;a.pits[p]++;n--}if((side===0?p<6:p>6&&p<13)&&a.pits[p]===1&&a.pits[12-p]>0){a.pits[side===0?6:13]+=a.pits[12-p]+1;a.pits[p]=a.pits[12-p]=0}if(a.pits.slice(0,6).every(n=>!n)||a.pits.slice(7,13).every(n=>!n)){for(let i=0;i<6;i++){a.pits[6]+=a.pits[i];a.pits[i]=0;a.pits[13]+=a.pits[i+7];a.pits[i+7]=0}a.message=a.pits[6]>a.pits[13]?'You win!':a.pits[6]===a.pits[13]?'Draw':'Computer wins';state='win';return true}a.turn=p===(side===0?6:13)?side:1-side;a.cool=.6;a.message=a.turn?'Computer turn':'Your turn';return true}
function extraInput(k){const a=extraState;if(extra==='bantumi'&&a.turn===0){if(['4','left'].includes(k))a.cursor=(a.cursor+5)%6;if(['6','right'].includes(k))a.cursor=(a.cursor+1)%6;if(['5','ok'].includes(k))sow(a,a.cursor,0)}if(extra==='pairs'){if(a.wait>0)return;const d={2:-4,up:-4,8:4,down:4,4:-1,left:-1,6:1,right:1}[k];if(d)a.cursor=(a.cursor+d+16)%16;if(['5','ok'].includes(k)&&!a.matched.has(a.cursor)&&!a.open.includes(a.cursor)){a.open.push(a.cursor);if(a.open.length===2){a.moves++;if(a.cards[a.open[0]]===a.cards[a.open[1]]){a.open.forEach(n=>a.matched.add(n));a.open=[];if(a.matched.size===16)state='win'}else a.wait=.8}}}if(extra==='mix'){const d={2:-4,up:-4,8:4,down:4,4:-1,left:-1,6:1,right:1}[k],n=a.blank+d;if(d&&n>=0&&n<16&&(Math.abs(d)===4||Math.floor(n/4)===Math.floor(a.blank/4))){[a.tiles[n],a.tiles[a.blank]]=[a.tiles[a.blank],a.tiles[n]];a.blank=n;a.moves++;if(a.tiles.every((n,i)=>n===(i+1)%16))state='win'}}if(extra==='pinball'&&['5','ok'].includes(k)&&a.ball.ready){a.ball.ready=false;a.ball.vx=-45;a.ball.vy=-160}if(extra==='dance'){const lane={4:0,left:0,2:1,up:1,8:2,down:2,6:3,right:3}[k];if(lane!==undefined){const n=a.schedule.find(n=>!n.done&&n.lane===lane&&Math.abs(n.at-a.t)<.23);if(n){n.done=true;a.combo++;a.hits++;a.points+=10+a.combo;beep(440+lane*120)}else a.combo=0}}}
action=function(k){if(document.body.classList.contains('choosing'))return;if(k==='power'||k==='0'){baseAction(k);return}if(state==='off')return;if(state==='games'){const p=phones[phoneId];if(['2','up'].includes(k))gameChoice=(gameChoice+p.ids.length-1)%p.ids.length;if(['8','down'].includes(k))gameChoice=(gameChoice+1)%p.ids.length;if(k==='back'){document.querySelector('#phones').click();return}if(['5','ok'].includes(k)){const id=p.ids[gameChoice];held.clear();if(['snake','impact'].includes(id)){extra=null;game=id;state=id==='snake'?'snake-menu':'menu';selection=snakeChoice=0}else{extra=id;state='extra-menu';extraState=null}}return}if(!extra){baseAction(k);return}if(state==='extra-menu'){if(k==='back')state='games';if(['ok','5'].includes(k))startExtra();return}if(state==='pause'){if(['5','ok','hash'].includes(k))state='play';if(k==='back')state='extra-menu';return}if(state==='over'||state==='win'){if(['5','ok'].includes(k))startExtra();if(k==='back')state='extra-menu';return}if(['back','hash'].includes(k)){state='pause';held.clear();return}if(state==='play')extraInput(k)};
update=function(dt){if(document.body.classList.contains('choosing'))return;if(!extra){baseUpdate(dt);return}if(state!=='play')return;const a=extraState;a.t+=dt;a.cool-=dt;if(extra==='bantumi'&&a.turn===1&&a.cool<=0){const opts=[7,8,9,10,11,12].filter(p=>a.pits[p]);const p=opts.find(p=>p+a.pits[p]===13)??opts.reduce((best,p)=>a.pits[p]>a.pits[best]?p:best,opts[0]);sow(a,p,1)}if(extra==='pairs'&&a.wait>0){a.wait-=dt;if(a.wait<=0)a.open=[]}if(extra==='dance'){a.schedule.filter(n=>!n.done&&n.at<a.t-.23).forEach(n=>{n.done=true;a.combo=0});a.stage=Math.min(3,1+Math.floor(a.t/16));if(a.t>50)state='win'}if(extra==='pinball'){const b=a.ball;if(b.ready)return;b.vy+=110*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.x<7||b.x>185){b.vx*=-.92;b.x=Math.max(7,Math.min(185,b.x))}if(b.y<21){b.y=21;b.vy=Math.abs(b.vy)}for(const [x,y]of [[48,42],[96,59],[143,39]]){const dx=b.x-x,dy=b.y-y,r=Math.hypot(dx,dy);if(r<13){b.vx=dx/r*115;b.vy=dy/r*115;b.x=x+dx/r*14;b.y=y+dy/r*14;a.points+=25;beep(700)}}const left=held.has('4')||held.has('left'),right=held.has('6')||held.has('right');if(b.y>96&&b.y<109&&b.vy>0&&((left&&b.x>25&&b.x<92)||(right&&b.x>100&&b.x<167))){b.vy=-145;b.vx=b.x<96?55:-55;a.points+=5}if(b.y>130){a.lives--;if(a.lives===0)state='over';else a.ball={x:177,y:108,vx:0,vy:0,ready:true}}}if(extra==='spider'){a.inv-=dt;a.x=Math.max(8,Math.min(184,a.x+((held.has('6')||held.has('right')?1:0)-(held.has('4')||held.has('left')?1:0))*85*dt));if(held.has('5')&&a.cool<=0){a.shots.push({x:a.x,y:110,vy:-145});a.cool=.2}for(const e of a.items){e.x=e.base+Math.sin(a.t*1.5)*9;e.y+=dt*(1+a.stage*.6);if(Math.random()<dt*(.12+a.stage*.04))a.shots.push({x:e.x,y:e.y+6,vy:45+a.stage*5})}for(const b of a.shots){b.y+=b.vy*dt;if(b.vy<0){const e=a.items.find(e=>e.hp>0&&Math.abs(e.x-b.x)<9&&Math.abs(e.y-b.y)<8);if(e){e.hp--;b.y=-100;a.points+=10}}else if(Math.abs(b.x-a.x)<7&&b.y>105&&b.y<118&&a.inv<=0){a.lives--;a.inv=1.5;b.y=200;if(a.lives<=0)state='over'}}a.shots=a.shots.filter(b=>b.y>15&&b.y<128);a.items=a.items.filter(e=>e.hp>0);if(a.items.some(e=>e.y>103))state='over';if(!a.items.length){if(a.stage===6)state='win';else{a.stage++;spiderWave()}}}};
function line(x,y,xx,yy,width=1){c.strokeStyle=ink;c.lineWidth=width;c.beginPath();c.moveTo(x,y);c.lineTo(xx,yy);c.stroke();c.lineWidth=1}
draw=function(){if(document.body.classList.contains('choosing'))return;if(state==='games'){c.fillStyle=paper;c.fillRect(0,0,W,H);menuRows('NOKIA '+phoneId,phones[phoneId].games,gameChoice);text('Recreations · C: phones',96,112,8,'center');return}if(!extra){baseDraw();if(phoneId==='3310'&&game==='impact'&&state==='menu'){c.fillStyle=paper;c.fillRect(45,43,143,18);text('IMPACT',111,57,16,'center')}if(phoneId==='6600'&&game==='snake'&&state==='snake-menu'){c.fillStyle=paper;c.fillRect(0,0,192,20);text('SNAKE EX · REMAKE',96,15,12,'center')}return}c.fillStyle=paper;c.fillRect(0,0,W,H);if(state==='off')return;const name=phones[phoneId].games[phones[phoneId].ids.indexOf(extra)];text(name.toUpperCase(),96,12,11,'center');if(state==='extra-menu'){help[extra].forEach((s,i)=>text(s,96,32+i*13,9,'center'));text('Fan-made recreation',96,105,8,'center');text('5: Start    C: Games',96,123,9,'center');return}const a=extraState;if(!a)return;if(extra==='bantumi'){text('CPU '+a.pits[13]+'    YOU '+a.pits[6],96,30,10,'center');for(let i=0;i<6;i++){const x=17+i*29;for(const [p,y]of [[12-i,53],[i,83]]){c.strokeStyle=ink;c.strokeRect(x-10,y-12,24,21);text(a.pits[p],x+2,y+3,12,'center')}if(a.cursor===i)rect(x-9,95,22,3)}text(a.message,96,115,9,'center')}if(extra==='pairs'||extra==='mix'){for(let i=0;i<16;i++){const x=39+(i%4)*29,y=23+Math.floor(i/4)*22;c.strokeStyle=ink;c.strokeRect(x,y,26,20);if(extra==='pairs'){const show=a.matched.has(i)||a.open.includes(i);text(show?String(a.cards[i]+1):'?',x+13,y+14,12,'center');if(i===a.cursor)c.strokeRect(x+2,y+2,22,16)}else if(a.tiles[i]){c.fillStyle=['#a8c5ce','#becab4','#d4be91'][Math.floor((a.tiles[i]-1)/5)];c.fillRect(x+1,y+1,24,18);text(a.tiles[i],x+13,y+14,11,'center')}}text('Moves '+a.moves,96,123,9,'center')}if(extra==='pinball'){text('SCORE '+a.points+'  BALLS '+a.lives,96,24,8,'center');for(const [x,y]of [[48,42],[96,59],[143,39]]){c.strokeStyle='#ba5b38';c.beginPath();c.arc(x,y,10,0,7);c.stroke();text('+',x,y+4,12,'center')}line(5,20,5,119);line(187,20,187,119);line(28,102,87,held.has('4')||held.has('left')?88:114,5);line(164,102,105,held.has('6')||held.has('right')?88:114,5);rect(a.ball.x-2,a.ball.y-2,5,5);if(a.ball.ready)text('5: LAUNCH',96,87,10,'center')}if(extra==='dance'){text('SONG '+a.stage+'   '+a.points,96,25,9,'center');line(15,96,177,96,2);['<','^','v','>'].forEach((s,i)=>text(s,35+i*40,114,14,'center'));for(const n of a.schedule){const y=96-(n.at-a.t)*65;if(!n.done&&y>30&&y<111)text(['<','^','v','>'][n.lane],35+n.lane*40,y,14,'center')}text('COMBO '+a.combo,96,126,8,'center')}if(extra==='spider'){text('WAVE '+a.stage+'  '+a.points+'  ♥'+a.lives,96,24,8,'center');a.items.forEach(e=>sprite('bug',e.x-4,e.y,1));a.shots.forEach(b=>rect(b.x,b.y,2,4));if(a.inv<=0||Math.floor(a.inv*10)%2===0){rect(a.x-5,112,11,4);rect(a.x-1,107,3,6)}}if(state==='pause')panel('PAUSED','5: Resume','C: game menu');if(state==='over')panel('GAME OVER','Score '+a.points,'5: Retry   C: menu');if(state==='win')panel(extra==='bantumi'?a.message:'WELL PLAYED!',['pairs','mix'].includes(extra)?'Moves '+a.moves:'Score '+a.points,'5: Play again  C: menu')};
